import axios from 'axios';
import { Message } from 'element-ui';

import store from '@/store/index.js';

axios.defaults.withCredentials = true;
let service = axios.create({
    baseURL: 'http://127.0.0.1:25125/api/',
    timeout: 60000,
    isLoading: true
});


// 请求拦截 可在请求头中加入token等
service.interceptors.request.use(
    config => {
        if (config.url.indexOf('?') >= 0) {
            config.url += '&_t=' + new Date().getTime();
        } else {
            config.url += '?_t=' + new Date().getTime();
        }

        // let token = store.state.User.userInfo.token;
        // if (token) {
        //     config.headers['X-Auth-Token'] = token;
        //     // config.headers['X-Auth-Token'] = '03031389-fd4e-46f8-91e4-1c15b5d572d4'
        // }

        return config;
    },
    error => {
        return Promise.reject(error);
    }
);

// 响应拦截 对响应消息作初步的处理
service.interceptors.response.use(
    resp => {
        let data = resp.data;

        if (data.code != 200 && data.code != 1000 && data.code != undefined) {
            try {
                Message.error({
                    message: data.msg
                });
            } catch (error) {}
        }

        return data;
    },
    err => {
        
        if (err.message !== '取消请求') {
            if (err && err.response) {
                switch (err.response.code) {
                    case 400:
                        err.message = '错误请求';
                        break;
                    case 401:
                        err.message = '登录信息失效';
                        break;
                    case 403:
                        err.message = '拒绝访问';
                        break;
                    case 404:
                        err.message = '请求错误,未找到该资源';
                        break;
                    case 405:
                        err.message = '请求方法未允许';
                        break;
                    case 408:
                        err.message = '请求超时';
                        break;
                    case 500:
                        err.message = '服务器端出错';
                        break;
                    case 501:
                        err.message = '网络未实现';
                        break;
                    case 502:
                        err.message = '网络错误';
                        break;
                    case 503:
                        err.message = '服务不可用';
                        break;
                    case 504:
                        err.message = '网络超时';
                        break;
                    case 505:
                        err.message = 'http版本不支持该请求';
                        break;
                    default:
                        err.message = `连接错误${err.response.code}`;
                }
            } else {
                err.message = '网络异常，请稍后再试...';
            }
            Message.error({ message: err.message });
        }

        return err;
    }
);

export default service;
